let appearanceBase={};
function iconSvg(id){const geometry=Object.hasOwn(slotforgeIconArt,id)?slotforgeIconArt[id]:slotforgeIconArt['other-part'];return `<svg viewBox="0 0 256 256" aria-hidden="true" focusable="false">${geometry}</svg>`;}
function itemIcon(item){return iconSvg(slotforgeIcons.resolve(item));}
function iconColour(item){return Object.hasOwn(slotforgeIcons.colours,item.iconColour)?item.iconColour:'auto';}
function appearanceEditor(item){
  appearanceBase=item;
  const colour=iconColour(item),selected=slotforgeIcons.icons.some(i=>i.id===item.iconId)?item.iconId:'',automatic=slotforgeIcons.automatic(item);
  return `<section class="item-appearance mt"><h3>Icon & colour</h3><p class="tiny muted">Automatic follows the category and part type. Choose another icon or a colour to identify a manufacturer or organise your collection.</p><div class="appearance-preview"><div id="item-icon-preview" class="item-visual" data-icon-colour="${colour}">${itemIcon(item)}</div><div><strong id="item-icon-label">${selected?esc(slotforgeIcons.icons.find(i=>i.id===selected).label):'Automatic'}</strong><div class="tiny muted">An uploaded photograph takes priority; your icon choice is kept.</div></div></div><fieldset class="icon-colours"><legend>Icon colour</legend>${Object.entries(slotforgeIcons.colours).map(([id,label])=>`<label class="icon-colour-choice"><input type="radio" name="iconColour" value="${id}" ${id===colour?'checked':''}><span class="colour-dot" data-icon-colour="${id}" aria-hidden="true"></span><span>${label}</span></label>`).join('')}</fieldset><details class="icon-picker"><summary>Choose an icon <span class="tiny muted">${slotforgeIcons.icons.length} available</span></summary><div class="icon-picker-toolbar"><label class="field">Search icons<input type="search" id="icon-search" placeholder="Motor, tyre, tool…"></label><label class="field">Category<select id="icon-group"><option value="">All categories</option>${Object.keys(slotforgeIcons.groups).map(g=>`<option>${esc(g)}</option>`).join('')}</select></label></div><fieldset class="icon-options" data-icon-colour="${colour}"><legend class="sr-only">Part icon</legend><label class="icon-option icon-automatic"><input type="radio" name="iconId" value="" ${!selected?'checked':''}><span id="automatic-icon-art">${iconSvg(automatic)}</span><span>Automatic</span></label>${slotforgeIcons.icons.map(i=>`<label class="icon-option" data-icon-option="${i.id}" data-icon-group="${esc(i.group)}"><input type="radio" name="iconId" value="${i.id}" ${i.id===selected?'checked':''}>${iconSvg(i.id)}<span>${esc(i.label)}</span></label>`).join('')}</fieldset><p id="icon-search-empty" class="tiny muted" hidden>No matching icons. Try another search or category.</p></details></section>`;
}
function currentItemAppearance(){const form=document.querySelector('#modal-form');return {category:form?.elements.namedItem('category')?.value??form?.elements.namedItem('supply-category')?.value??appearanceBase.category??'',partType:form?.elements.namedItem('partType')?.value??appearanceBase.partType??'',iconId:form?.elements.namedItem('iconId')?.value||'',iconColour:form?.elements.namedItem('iconColour')?.value||'auto',picture:inventoryPhoto,name:'Selected photograph'};}
function editPartAppearance(id){const part=db.parts.find(p=>p.id===id),revision=db.revision;inventoryPhoto=part.picture||'';modal('Icon & colour · '+part.name,appearanceEditor(part),async values=>{await change('part.appearance',{id,revision,data:{iconId:values.iconId,iconColour:values.iconColour}});},'Save appearance');}
function refreshItemAppearance(){
  const preview=document.querySelector('#item-icon-preview');if(!preview)return;const item=currentItemAppearance();preview.innerHTML=itemIcon(item);preview.dataset.iconColour=iconColour(item);
  document.querySelector('#item-icon-label').textContent=item.iconId?slotforgeIcons.icons.find(i=>i.id===item.iconId)?.label||'Automatic':'Automatic';
  document.querySelector('#automatic-icon-art').innerHTML=iconSvg(slotforgeIcons.automatic(item));document.querySelector('.icon-options').dataset.iconColour=iconColour(item);
  const photoPreview=document.querySelector('#item-photo-preview');if(photoPreview)photoPreview.innerHTML=itemVisual(item);
}
function filterIconOptions(){const query=document.querySelector('#icon-search').value.trim().toLowerCase(),group=document.querySelector('#icon-group').value;let visible=0;for(const tile of document.querySelectorAll('[data-icon-option]')){const match=(!group||tile.dataset.iconGroup===group)&&(!query||(tile.textContent+' '+tile.dataset.iconGroup+' '+tile.dataset.iconOption).toLowerCase().includes(query));tile.hidden=!match;if(match)visible++;}document.querySelector('#icon-search-empty').hidden=visible>0;}
document.addEventListener('input',event=>{if(event.target.id==='icon-search')filterIconOptions();if(['partType','iconId','iconColour'].includes(event.target.name))refreshItemAppearance();});
document.addEventListener('change',event=>{if(event.target.id==='icon-group')filterIconOptions();if(['category','supply-category','partType','iconId','iconColour'].includes(event.target.name))refreshItemAppearance();});
